(function () use ($promo, $total) {
                $percentDiscount = (int) round(($promo->amount / 100) * $total);
                $maxDiscount = (int) ($promo->max_discount_amount ?? 0);

                if ($maxDiscount > 0) {
                    return min($percentDiscount, $maxDiscount);
                }

                return $percentDiscount;
            })
